mapper.select:
select w.id as `id`, w.warning_type as `warningType`, w.warning_grade as `warningGrade`, w.node_id as `nodeId`, w.node_type as `nodeType`, w.stack_id as `stackId`, w.area_id as `areaId`, w.is_affirm as `isAffirm`, w.task_id as `taskId`, date_format(w.warning_time, '%Y-%m-%d %H:%i:%s') as `warningTime`, date_format(w.deal_time, '%Y-%m-%d %H:%i:%s') as `dealTime`, w.site_route as `siteRoute` from tb_early_warning w where 1 = 1
and w.warning_time >= #{beginTime}
and w.warning_time <= #{endTime}
and (w.stack_id = #{stackId} or (w.area_id = #{areaId} and w.warning_type in ('05','07','09','11','14')))
and w.stack_id = #{stackId}
and w.area_id = #{areaId}
and 1 = 0
order by w.warning_time, w.id

select h.id as `id`, h.pest_board_id as `pestBoardId`, h.gather_site as `gatherSite`, date_format(h.gather_time, '%Y-%m-%d %H:%i:%s') as `gatherTime`, ifnull(h.beetle_count, 0) as `beetleCount`, ifnull(h.mealworm_count, 0) as `mealwormCount`, ifnull(h.alert_level, 0) as `alertLevel`, h.site_route as `siteRoute`, b.site_name as `boardSiteName` from tb_pest_data_history h left join tb_pest_board b on b.pest_board_id = h.pest_board_id where 1 = 1
and h.gather_time >= #{beginTime}
and h.gather_time <= #{endTime}
and (b.site_id = #{areaId} or h.site_route like concat('%,', #{areaId}))
order by h.gather_time, h.id
